package org.brightstats.desktop;

import java.util.*;
import org.brightstats.stats.PcaRotation;
import javafx.scene.control.*;
import javafx.scene.layout.VBox;
import javafx.geometry.Insets;
import javafx.stage.Window;

final class PcaDialog {
    record Settings(int[] columns,boolean correlation,int components,PcaRotation.Options rotation){Settings(int[] columns,boolean correlation,int components){this(columns,correlation,components,PcaRotation.Options.defaults());}Settings{rotation=rotation==null?PcaRotation.Options.defaults():rotation;columns=columns.clone();if(columns.length==0||Arrays.stream(columns).anyMatch(i->i<0)||Arrays.stream(columns).distinct().count()!=columns.length||components<1||components>columns.length)throw new IllegalArgumentException("Choose distinct variables and a valid component count.");}@Override public int[] columns(){return columns.clone();}}
    private final Dialog<Settings> dialog=new Dialog<>();private final ListView<String> columns=new ListView<>();private final CheckBox correlation=new CheckBox("Use correlation matrix (sample-standardize variables)");private final TextField components=new TextField();private final Label error=new Label();private Settings settings;private final ComboBox<PcaRotation.Method> rotation=new ComboBox<>();private final CheckBox normalize=new CheckBox("Kaiser-normalize loading rows before varimax");private final TextField power=new TextField("4"),limit=new TextField("1000"),tolerance=new TextField("1e-8");
    private PcaDialog(Window owner,List<String> names,Settings previous){dialog.initOwner(owner);dialog.setTitle("Principal components");columns.getItems().setAll(names);columns.getSelectionModel().setSelectionMode(SelectionMode.MULTIPLE);columns.setPrefHeight(230);if(previous==null){columns.getSelectionModel().selectAll();correlation.setSelected(true);components.setText(Integer.toString(Math.min(3,names.size())));}else{for(int index:previous.columns())columns.getSelectionModel().select(index);correlation.setSelected(previous.correlation());components.setText(Integer.toString(previous.components()));}rotation.getItems().setAll(PcaRotation.Method.values());var prior=previous==null?PcaRotation.Options.defaults():previous.rotation();rotation.setValue(prior.method());normalize.setSelected(prior.kaiserNormalization());power.setText(Integer.toString(prior.power()));limit.setText(Integer.toString(prior.maxIterations()));tolerance.setText(Double.toString(prior.tolerance()));error.setWrapText(true);VBox content=new VBox(10,UiAppearance.label("Variables"),columns,correlation,UiAppearance.label("Retained component count"),components,UiAppearance.label("Rotation"),rotation,normalize,UiAppearance.label("Promax power (2-6)"),power,UiAppearance.label("Maximum rotation iterations"),limit,UiAppearance.label("Rotation tolerance"),tolerance,UiAppearance.label("Variables are centred; covariance uses n−1. Missing values must be prepared first."),error);content.setPadding(new Insets(12));content.setPrefWidth(600);ScrollPane scroll=new ScrollPane(content);scroll.setFitToWidth(true);scroll.setPrefViewportHeight(610);dialog.getDialogPane().setContent(scroll);dialog.getDialogPane().getButtonTypes().setAll(ButtonType.OK,ButtonType.CANCEL);dialog.getDialogPane().lookupButton(ButtonType.OK).addEventFilter(javafx.event.ActionEvent.ACTION,event->{settings=null;try{settings=new Settings(columns.getSelectionModel().getSelectedIndices().stream().mapToInt(Integer::intValue).toArray(),correlation.isSelected(),Integer.parseInt(components.getText().trim()),new PcaRotation.Options(rotation.getValue(),normalize.isSelected(),Integer.parseInt(limit.getText().trim()),Double.parseDouble(tolerance.getText().trim()),Integer.parseInt(power.getText().trim())));}catch(Exception problem){event.consume();error.setText(problem.getMessage());}});dialog.setResultConverter(button->button==ButtonType.OK?settings:null);}
    static Optional<Settings> show(Window owner,List<String> names,Settings previous){return new PcaDialog(owner,names,previous).dialog.showAndWait();}
    static Settings smokeTest(Window owner,List<String> names){var test=new PcaDialog(owner,names,null);test.dialog.show();test.columns.getSelectionModel().clearSelection();test.columns.getSelectionModel().selectIndices(0,1,2);test.components.setText("4");((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!test.dialog.isShowing()||test.settings!=null)throw new AssertionError("Invalid PCA component count accepted");test.components.setText("2");((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(test.dialog.getResult()==null||test.dialog.getResult().components()!=2)throw new AssertionError("PCA dialog changed settings");return test.dialog.getResult();}
}
